 render(){this.ensure();const sf=window.SF;sf.$('workspace').innerHTML=`<div class="commerce-shell markets-shell"><header class="commerce-head"><div><div class="section-kicker">SALES & BUSINESS</div><h2>Markets & Shows</h2><p class="muted">The original compact market workflow, now connected to shared inventory, expenses, calendar and reporting.</p></div><button class="button primary" id="newMarketEvent">＋ New Event</button></header><nav class="market-workspace-tabs">${this.tabs.map(([id,l])=>`<button data-market-tab="${id}" class="${this.tab===id?'active':''}">${l}</button>`).join('')}</nav><div id="marketsBody"></div></div>`;document.querySelectorAll('[data-market-tab]').forEach(b=>b.onclick=()=>{this.tab=b.dataset.marketTab;this.render()});sf.$('newMarketEvent').onclick=()=>this.openEvent();this.draw()},
