 history(){const sf=window.SF,events=this.marketEvents(),tx=sf.state.salesTransactions.filter(t=>events.some(e=>e.id===t.eventId)).sort((a,b)=>String(b.soldAt||b.createdAt).localeCompare(String(a.soldAt||a.createdAt)));sf.$('marketsBody').innerHTML=`<section class="card"><h3>Transactions</h3><p class="muted">Each customer receipt appears once. Edit or delete an entry when a sale was entered incorrectly.</p><div class="market-history-list">${tx.length?tx.map(t=>{const e=events.find(x=>x.id===t.eventId);return `<article class="market-history-card"><div><b>${sf.esc(e?.name||'Market / Show')}</b><small>${String(t.soldAt||'').slice(0,10)} · ${sf.esc(t.paymentMethod||'')}</small>${(t.lineItems||[]).map(x=>`<span>${Number(x.qty||1)} × ${sf.esc(x.productName||'Product')} · ${sf.esc(x.artworkTitle||'Artwork')}</span>`).join('')}</div><strong>${this.money(t.total)}</strong><div class="history-actions"><button class="button secondary" data-edit-sale="${t.id}">Edit</button><button class="button danger" data-delete-sale="${t.id}">Delete</button></div></article>`}).join(''):'<div class="empty-state roomy">No transactions recorded.</div>'}</div></section>`;document.querySelectorAll('[data-edit-sale]').forEach(b=>b.onclick=()=>this.openSaleEdit(b.dataset.editSale));document.querySelectorAll('[data-delete-sale]').forEach(b=>b.onclick=()=>this.deleteSale(b.dataset.deleteSale))},
