  <section class="event-artwork-box" id="galleryArtworkSection"><div class="commerce-toolbar"><div><h3>Artwork Out / Returned</h3><p class="muted">Used only for Art Shows and Gallery Exhibitions. Markets continue deducting inventory directly from recorded sales.</p></div><button type="button" class="button secondary" id="addTrackedArtwork">＋ Add Artwork</button></div><div id="trackedArtworkRows">${tracked.map(r=>`<div class="tracked-art-row"><select data-track-art>${arts.map(a=>`<option value="${sf.esc(a.artworkId||a.id)}" ${String(r.artworkId)===String(a.artworkId||a.id)?'selected':''}>${sf.esc(a.title||'Untitled')}</option>`).join('')}</select><select data-track-status><option value="out" ${r.status!=='returned'?'selected':''}>Out at event</option><option value="returned" ${r.status==='returned'?'selected':''}>Returned</option></select><button type="button" class="button danger remove-tracked-art">Remove</button></div>`).join('')}</div></section>
